from __future__ import annotations

from datetime import datetime, timedelta


_MONTH_NAMES = {
    "JAN": 1,
    "FEB": 2,
    "MAR": 3,
    "APR": 4,
    "MAY": 5,
    "JUN": 6,
    "JUL": 7,
    "AUG": 8,
    "SEP": 9,
    "OCT": 10,
    "NOV": 11,
    "DEC": 12,
}

_DAY_NAMES = {
    "SUN": 0,
    "MON": 1,
    "TUE": 2,
    "WED": 3,
    "THU": 4,
    "FRI": 5,
    "SAT": 6,
}


def _parse_number(text):
    """Parse a non-negative decimal integer, rejecting signs and junk."""
    if not text or not text.isascii() or not text.isdigit():
        raise ValueError("invalid cron value: %r" % (text,))
    return int(text)


def _parse_value(text, minimum, maximum, names):
    """Parse one endpoint of an item, resolving month/day names."""
    if names is not None:
        value = names.get(text.upper())
        if value is None:
            value = _parse_number(text)
    else:
        value = _parse_number(text)
    if value < minimum or value > maximum:
        raise ValueError("cron value out of range: %r" % (text,))
    return value


def _parse_field(field, minimum, maximum, names, label):
    """Expand one cron field into the set of values it matches."""
    values = set()
    for item in field.split(","):
        if not item:
            raise ValueError("empty item in %s field" % (label,))

        parts = item.split("/")
        if len(parts) > 2:
            raise ValueError("malformed item in %s field: %r" % (label, item))
        base = parts[0]
        has_step = len(parts) == 2
        if has_step:
            step = _parse_number(parts[1])
            if step <= 0:
                raise ValueError("invalid step in %s field: %r" % (label, item))
        else:
            step = 1

        if base == "*":
            start, end = minimum, maximum
        elif "-" in base:
            bounds = base.split("-")
            if len(bounds) != 2 or not bounds[0] or not bounds[1]:
                raise ValueError(
                    "malformed item in %s field: %r" % (label, item)
                )
            start = _parse_value(bounds[0], minimum, maximum, names)
            end = _parse_value(bounds[1], minimum, maximum, names)
            if start > end:
                raise ValueError(
                    "descending range in %s field: %r" % (label, item)
                )
        else:
            start = _parse_value(base, minimum, maximum, names)
            end = maximum if has_step else start

        values.update(range(start, end + 1, step))

    return values


def _add_years(value, years):
    """Add calendar years, clamping Feb 29 and the end of datetime."""
    total = value.year + years
    if total > datetime.max.year:
        return datetime.max
    try:
        return value.replace(year=total)
    except ValueError:
        # Feb 29 in a year that is not a leap year.
        return value.replace(year=total, month=2, day=28)


def _next_time(hours, minutes, minimum_hour, minimum_minute):
    """The first (hour, minute) at or after the given lower bound."""
    for hour in hours:
        if hour < minimum_hour:
            continue
        if hour == minimum_hour:
            for minute in minutes:
                if minute >= minimum_minute:
                    return hour, minute
        else:
            return hour, minutes[0]
    return None


def _day_matches(day, days_of_month, days_of_week, both_restricted):
    dom_match = day.day in days_of_month
    # Python: Monday == 0.  Cron: Sunday == 0 (and 7 is Sunday too).
    cron_dow = (day.weekday() + 1) % 7
    dow_match = cron_dow in days_of_week
    if both_restricted:
        return dom_match or dow_match
    return dom_match and dow_match


def next_run(expression: str, after: datetime) -> datetime:
    """The first time after ``after`` that ``expression`` fires."""
    if not isinstance(expression, str):
        raise ValueError("cron expression must be a string")

    fields = expression.split()
    if len(fields) != 5:
        raise ValueError("cron expression must have exactly five fields")
    minute_field, hour_field, dom_field, month_field, dow_field = fields

    minutes = sorted(_parse_field(minute_field, 0, 59, None, "minute"))
    hours = sorted(_parse_field(hour_field, 0, 23, None, "hour"))
    days_of_month = _parse_field(dom_field, 1, 31, None, "day-of-month")
    months = _parse_field(month_field, 1, 12, _MONTH_NAMES, "month")
    days_of_week = _parse_field(dow_field, 0, 7, _DAY_NAMES, "day-of-week")

    # Normalise cron's alternate Sunday representation to 0.
    days_of_week = {0 if value == 7 else value for value in days_of_week}

    # Vixie cron ORs day-of-month and day-of-week only when both are
    # restricted.  The check is textual: only a bare "*" is unrestricted.
    both_restricted = dom_field != "*" and dow_field != "*"

    # The earliest minute-aligned instant strictly after ``after``.
    try:
        start = after.replace(second=0, microsecond=0) + timedelta(minutes=1)
    except OverflowError:
        raise ValueError("no matching time within five years") from None

    deadline = _add_years(after, 5)
    current = start.date()
    last = deadline.date()

    while current <= last:
        if current.month in months and _day_matches(
            current, days_of_month, days_of_week, both_restricted
        ):
            if current == start.date():
                minimum_hour, minimum_minute = start.hour, start.minute
            else:
                minimum_hour, minimum_minute = 0, 0

            found = _next_time(
                hours, minutes, minimum_hour, minimum_minute
            )
            if found is not None:
                candidate = datetime(
                    current.year, current.month, current.day, found[0], found[1]
                )
                if candidate <= deadline:
                    return candidate

        if current == last:
            break
        current += timedelta(days=1)

    raise ValueError("no matching time within five years")
